	@Test
	void readAheadFiltersInheritTheCallersDecodedInputAccounting() throws IOException {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1L << 20, 1L << 20);
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		RowState row = row(new CountingSource());
		row.enableDecodedInputAccounting();
		LmdbNativeValueCodec codec = mock(LmdbNativeValueCodec.class);
		LmdbNativeValueCodec.DecodedValue decoded = LmdbNativeValueCodec.fromValue(
				SimpleValueFactory.getInstance().createLiteral("accounted support input ".repeat(128)));
		when(codec.decodeAssured(1L, ValuePosition.NONE)).thenReturn(decoded);
		int[] calls = { 0 };
		NativeBooleanFilter condition = new NativeBooleanFilter() {
			@Override
			public boolean accept(RowState state) {
				long before = manager.usedBytes();
				assertThat(state.decodedValue(0, codec, true)).isSameAs(decoded);
				if (calls[0]++ == 0) {
					assertThat(manager.usedBytes() - before).as("the read-ahead frame charges retained decoded inputs")
							.isEqualTo(RowState.decodedInputMemoryBytes(state.slots.length) + decoded.ownedBytes());
				}
				return true;
			}

			@Override
			public NativePredicateCapabilities capabilities() {
				return NativePredicateCapabilities.snapshot(1L, true, false);
			}
		};
		try {
			FilterPlan left = new FilterPlan(outerRows(false, false), condition, 1L);
			try (RowCursor cursor = LmdbNativeSupportJoin.tryOpen(left, pattern(), row, true)) {
				assertThat(cursor).as("the pure filtered VALUES input is eligible for read-ahead").isNotNull();
				assertThat(cursor.next()).isTrue();
				assertThat(calls[0]).isEqualTo(64);
			}
			assertThat(manager.usedBytes()).isZero();
		} finally {
			row.closeDecodedInputs();
			row.memoryScope.close();
			LmdbNativeHashJoin.queryMemoryOverride = previous;
		}
	}

	@Test
	void weightedWindowFallbackMultipliesBothConsumingInputWeights() throws IOException {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1L << 20, 1L << 20);
		RowState row = row(new CountingSource());
		LmdbQueryMemoryManager.QueryLedger ledger = row.memoryScope.ledger(manager);
		LmdbQueryMemoryManager.Reservation metadata = ledger.reserve(128L << 10, null);
		LmdbAdaptiveLongArray window = LmdbAdaptiveLongArray.tryCreate(ledger,
				LmdbNativeSupportJoin.WINDOW_ROWS * (row.slots.length + 1));
		assertThat(metadata).isNotNull();
		assertThat(window).isNotNull();
		SlotPlan left = weightedRows(new int[] { 0, 1 }, new long[][] { { 1L, 100L }, { 1L, 101L } },
				new long[] { 2L, 3L }, new int[1]);
		int[] rightOpens = { 0 };
		SlotPlan right = weightedRows(new int[] { 2 }, new long[][] { { 11L }, { 12L } },
				new long[] { 3L, 5L }, rightOpens);
		long windowsBefore = LmdbNativeSupportJoin.MEMO_WINDOWS.get();
		long declinesBefore = LmdbNativeSupportJoin.COST_DECLINES.get();
		List<Long> weights = new ArrayList<>();
		// Custom plans have no native cost certificate: this deliberately tests the weighted fallback, not admission.
		try (var cursor = new LmdbNativeSupportJoin.WindowCursor(left, right, row, true, new int[] { 0 }, metadata,
				window)) {
			while (cursor.next()) {
				weights.add(cursor.multiplicity());
			}
		} finally {
			row.memoryScope.close();
		}
		assertThat(weights).containsExactly(6L, 10L, 9L, 15L);
		assertThat(rightOpens[0]).isEqualTo(2);
		assertThat(LmdbNativeSupportJoin.MEMO_WINDOWS.get()).isEqualTo(windowsBefore);
		assertThat(LmdbNativeSupportJoin.COST_DECLINES.get()).isGreaterThan(declinesBefore);
		assertThat(manager.usedBytes()).isZero();
	}

